extern "C" fn putchar(n: i32) -> i32;
resource Ticket { code: i32 }
impl Drop for Ticket { fn drop(self: Self) { unsafe { putchar(.code) } } }
package Leaf { manages ticket: Ticket; value: i32 }
package Item { first: Leaf; second: Leaf; tag: i32 }
fn make() -> impl Fn() -> i32 {
    let items: Store<Item> = store_new()
    store_reserve(items, 2)
    store_push(items, Item { first: Leaf { ticket: Ticket { code: 65 }, value: 7 }, second: Leaf { ticket: Ticket { code: 66 }, value: 9 }, tag: 3 })
    return move () => { return i32(store_len(items)) }
}
package State<F> { manages tag: Ticket; callback: F }
fn pack<F: Fn() -> i32>(callback: F) -> State<F> {
    return State::<F> { tag: Ticket { code: 90 }, callback: callback }
}
fn run<F: Fn() -> i32>(state: State<F>) -> i32 {
    let outer: Store<State<F>> = store_new()
    if !store_reserve(outer, 1) { return 1 }
    store_push(outer, state)
    return store_at(outer, 0).callback() - 1
}
fn main() -> i32 { return run(pack(make())) }
